package com.example.expensetracker.ui.transactions;
import android.content.*; import android.os.Bundle; import android.view.View; import android.widget.*; import android.text.*;
import androidx.appcompat.app.AppCompatActivity; import androidx.lifecycle.ViewModelProvider; import androidx.recyclerview.widget.*;
import com.example.expensetracker.R; import com.example.expensetracker.data.local.TransactionEntity; import com.example.expensetracker.ui.add.AddTransactionActivity; import com.google.android.material.button.MaterialButton; import com.google.android.material.dialog.MaterialAlertDialogBuilder; import java.util.*;
public class TransactionActivity extends AppCompatActivity {
 private TransactionViewModel vm; private TransactionAdapter adapter; private TextView empty,count; private EditText search; private Spinner filter; private List<TransactionEntity> all=new ArrayList<>(),shown=new ArrayList<>();
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_transactions);empty=findViewById(R.id.tvEmpty);search=findViewById(R.id.etSearch);filter=findViewById(R.id.spFilter);int countId=getResources().getIdentifier("tvCount","id",getPackageName());count=countId==0?null:findViewById(countId);
 RecyclerView rv=findViewById(R.id.rvTransactions);rv.setLayoutManager(new LinearLayoutManager(this));adapter=new TransactionAdapter(new ArrayList<>(),this::delete);rv.setAdapter(adapter);vm=new ViewModelProvider(this).get(TransactionViewModel.class);
 vm.getAll().observe(this,items->{all=items==null?new ArrayList<>():new ArrayList<>(items);applyFilter();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){applyFilter();}public void afterTextChanged(Editable e){}});filter.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?>p,View v,int pos,long id){applyFilter();}public void onNothingSelected(AdapterView<?>p){}});
 findViewById(R.id.btnAdd).setOnClickListener(v->startActivity(new Intent(this,AddTransactionActivity.class)));int exportId=getResources().getIdentifier("btnExport","id",getPackageName());if(exportId!=0)findViewById(exportId).setOnClickListener(v->exportCsv()); }
 private void applyFilter(){String q=search==null||search.getText()==null?"":search.getText().toString().trim().toLowerCase(Locale.ROOT);int mode=filter==null?0:filter.getSelectedItemPosition();shown.clear();for(TransactionEntity t:all){boolean typeOk=mode==0||(mode==1&&"EXPENSE".equals(t.type))||(mode==2&&"INCOME".equals(t.type));String hay=(t.title+" "+t.category+" "+t.notes).toLowerCase(Locale.ROOT);if(typeOk&&hay.contains(q))shown.add(t);}adapter.setItems(shown);empty.setVisibility(shown.isEmpty()?View.VISIBLE:View.GONE);if(count!=null)count.setText(shown.size()+" transaction"+(shown.size()==1?"":"s"));}
 private void delete(TransactionEntity t){new MaterialAlertDialogBuilder(this).setTitle("Delete transaction?").setMessage("This action cannot be undone.").setNegativeButton("Cancel",null).setPositiveButton("Delete",(d,w)->vm.delete(t)).show();}
 private void exportCsv(){if(shown.isEmpty()){Toast.makeText(this,"No transactions to export",Toast.LENGTH_SHORT).show();return;}StringBuilder csv=new StringBuilder("id,date,type,title,category,amount,notes\n");for(TransactionEntity t:shown)csv.append(t.id).append(',').append(quote(t.date)).append(',').append(quote(t.type)).append(',').append(quote(t.title)).append(',').append(quote(t.category)).append(',').append(t.amount).append(',').append(quote(t.notes)).append('\n');Intent send=new Intent(Intent.ACTION_SEND);send.setType("text/csv");send.putExtra(Intent.EXTRA_SUBJECT,"ExpenseTracker transactions");send.putExtra(Intent.EXTRA_TEXT,csv.toString());startActivity(Intent.createChooser(send,"Share CSV data"));}
 private String quote(String s){return "\""+(s==null?"":s.replace("\"","\"\""))+"\"";}
}
